window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["model-families"]={"title":"模型家族：从信息流与训练目标理解能力边界","subtitle":"不背品牌榜单，而是用架构、目标、模态与产品层四个轴，判断一个模型为什么擅长某类任务。","thesis":"模型家族不是厂商名单。<b>架构决定信息怎样流动，训练目标决定模型练习预测什么，数据与后训练塑造行为，产品层再增加检索、工具、记忆与权限。</b>只有把这些层拆开，才能从任务约束出发选择模型，而不是从品牌反推能力、隐私或可靠性。","quality":{"contractVersion":2,"sectionContracts":[{"section":1,"definition":{"answer":"模型家族是一套描述模型机制与交付方式的分析坐标，而不是品牌集合。","evidence":"不是品牌集合，而是一套描述模型机制与交付方式的坐标"},"problem":{"answer":"它解决只凭 Transformer 等单一标签无法判断模型能力的问题。","evidence":"为什么“它是 Transformer”远远不够"},"inputOutput":{"answer":"输入一个待分析模型，输出架构、训练目标、模态接口和产品层四项说明。","evidence":"输出是架构、训练目标、模态接口和后训练/产品层四项说明"},"mechanism":{"answer":"沿四个相互独立的轴逐项分析模型，而不把名称当作完整解释。","evidence":"信息怎样读取、保存与混合"},"interpretation":{"answer":"四轴结果说明模型为什么擅长某类任务，也暴露部署与行为约束。","evidence":"四轴帮助解释“为什么擅长”"},"boundary":{"answer":"家族标签不能替代版本核验和任务实测。","evidence":"仍要查具体版本并实测"}},{"section":2,"definition":{"answer":"编码器、解码器和编码器—解码器是三种不同的信息流组织方式。","evidence":"编码器、解码器与编码器—解码器的信息流不同"},"problem":{"answer":"它解释同样使用注意力的模型为什么适合不同任务。","evidence":"同样使用注意力，为什么适合的任务不同"},"inputOutput":{"answer":"编码器接收完整序列并输出各位置的双向表示。","evidence":"编码器输入完整序列并输出每个位置的双向表示"},"mechanism":{"answer":"因果解码器根据提示和已生成前缀逐位置预测下一个 token。","evidence":"因果解码器输入提示与已生成前缀"},"interpretation":{"answer":"应看训练信号和计算路径是否贴合任务，而不只看架构名称。","evidence":"训练信号与计算路径是否贴合任务"},"boundary":{"answer":"某种信息流的天然强项不等于其他任务完全做不了。","evidence":"天然强项”不是排他能力"}},{"section":3,"definition":{"answer":"扩散模型学习逐步去除噪声，而不是从左到右续写 token。","evidence":"扩散模型学习逐步去噪，不是从左到右续写"},"problem":{"answer":"它解释图像生成模型为何能从随机噪声逐步恢复结构。","evidence":"为什么图像生成常从噪声开始"},"inputOutput":{"answer":"训练输入是带噪样本、时间步与可选条件，输出是噪声或等价去噪目标的预测。","evidence":"训练输入是带噪样本、时间步和可选条件"},"mechanism":{"answer":"模型反复预测并移除噪声，逐步把随机变量恢复成有结构的样本。","evidence":"反复使用这些预测恢复结构"},"interpretation":{"answer":"一次更新可同时修正整幅潜变量，而非只追加末尾内容。","evidence":"可以同时修正整幅潜变量"},"boundary":{"answer":"传统扩散采样通常需要多次迭代，因此延迟可能较高。","evidence":"传统采样需要多步"}},{"section":4,"definition":{"answer":"状态空间与递归家族用压缩状态承载历史并进行线性扫描。","evidence":"状态空间与递归家族用压缩状态换线性扫描"},"problem":{"answer":"它解决不做所有位置两两比较时如何携带历史信息的问题。","evidence":"不做所有位置两两比较，模型如何携带历史"},"inputOutput":{"answer":"每个位置输入 xₜ 和旧状态，输出新状态及当前位置的 yₜ。","evidence":"xₜ 是当前位置输入"},"mechanism":{"answer":"矩阵 A 更新旧状态，B 写入当前输入，C 把新状态读成输出。","evidence":"矩阵 A 更新旧状态"},"interpretation":{"answer":"序列变长时，线性扫描的计算增长通常慢于全局注意力。","evidence":"递归或状态空间扫描步数只增加约四倍"},"boundary":{"answer":"需要精确随机访问或原样复制很早片段时，压缩状态可能吃亏。","evidence":"需要精确随机访问、原样复制早期片段时"}},{"section":5,"definition":{"answer":"多模态融合让图像、音频等表示与文本表示进入可相互影响的计算路径。","evidence":"多模态融合把图像、音频等表示与文本表示放进能够相互影响的计算路径"},"problem":{"answer":"它解决不同模态信息如何共同影响模型判断或生成的问题。","evidence":"图像加文本输入，是否就形成了统一理解"},"inputOutput":{"answer":"输入可以是图像、音频与文本，输出可为共享表示、文本、图像或动作。","evidence":"输出可以是共享表示、文本、图像或动作"},"mechanism":{"answer":"一种方式是用投影器把视觉向量转换成语言模型可读取的 token。","evidence":"投影器把向量变成语言模型可读 token"},"interpretation":{"answer":"流畅描述图片只说明生成路径可用，不证明所有视觉能力可靠。","evidence":"输出流畅地描述图片只证明生成路径可用"},"boundary":{"answer":"OCR、空间关系、计数和细粒度定位仍必须分别测试。","evidence":"OCR、空间关系、计数和细粒度定位都可靠"}},{"section":6,"definition":{"answer":"本节用退款助手展示先拆任务、再匹配模型家族的系统设计方法。","evidence":"为退款助手拆分任务，而非先挑品牌"},"problem":{"answer":"它回答退款助手是否需要由同一个大模型包办全部步骤。","evidence":"需要同一个模型包办吗"},"inputOutput":{"answer":"输入退款请求和准确率、模态、延迟、权限约束，输出分工后的系统方案。","evidence":"准确率·模态·延迟·权限"},"mechanism":{"answer":"先拆出意图分类、检索、票据读取与执行，再为各步选择合适组件。","evidence":"先拆任务与硬约束"},"interpretation":{"answer":"组合系统往往比单一最大模型更便宜、更可测且更可控。","evidence":"组合系统通常比“最大模型全包”更便宜、可测、可控"},"boundary":{"answer":"涉及退款执行等高风险动作时，应交给具有权限边界的工具。","evidence":"高风险动作交给有权限边界的工具"}},{"section":7,"definition":{"answer":"模型选择是先按硬约束过滤，再比较质量与成本前沿的过程。","evidence":"把硬约束先过滤，再比较质量—成本前沿"},"problem":{"answer":"它解决排行榜第一的模型未必适合具体业务的问题。","evidence":"排行榜第一为什么可能不是你的最佳模型"},"inputOutput":{"answer":"输入候选家族、规模和业务约束，输出可行候选及权衡结果。","evidence":"候选家族和规模"},"mechanism":{"answer":"先剔除不满足模态、延迟和部署约束的候选，再进行多目标比较。","evidence":"先筛硬约束：数据驻留、许可、模态、上下文、硬件、最大延迟"},"interpretation":{"answer":"示例数值只演示决策流程，不代表真实厂商性能。","evidence":"数字是教学算例，不代表真实厂商性能"},"boundary":{"answer":"不可把量纲和意义不同的指标随意相加为单一总分。","evidence":"不把异质指标随意加成总分"}},{"section":8,"definition":{"answer":"后训练是在基础模型之上改变行为表现的一组训练方法。","evidence":"后训练改变行为，但不会抹去基础机制"},"problem":{"answer":"它解释行为变化是否意味着模型已经换成一种新架构。","evidence":"“推理模型”“聊天模型”“工具模型”是新架构吗"},"inputOutput":{"answer":"输入监督数据、偏好或奖励信号，输出行为经过调整的模型。","evidence":"监督微调、偏好优化、强化学习和蒸馏"},"mechanism":{"answer":"训练信号调整模型参数，从而改变指令遵循、风格和工具调用。","evidence":"可显著改变回答风格、遵循指令、推理时计算与工具调用"},"interpretation":{"answer":"行为更可靠不能直接解释成基础模型记住了某个数据库。","evidence":"不能直接推断基础模型“记住了数据库”"},"boundary":{"answer":"后训练不能替代执行系统的真实鉴权与权限控制。","evidence":"真正权限在执行层"}},{"section":9,"definition":{"answer":"开放权重、API 和品牌描述的是交付层，而不是架构家族。","evidence":"开放权重、API 与品牌属于交付层，不是架构家族"},"problem":{"answer":"它解决从开放或 API 等标签误推隐私、安全和能力的问题。","evidence":"为什么都不成立"},"inputOutput":{"answer":"输入权重许可、代码数据开放度、托管位置与政策，输出部署风险判断。","evidence":"权重许可、训练代码、数据开放程度、托管位置和 API 数据政策"},"mechanism":{"answer":"开放权重提供自托管可能性，API 则由服务方托管并按接口交付。","evidence":"开放权重允许自托管"},"interpretation":{"answer":"不能仅凭交付名称直接推出模型能力、隐私或合规结论。","evidence":"不能从名称直接推出"},"boundary":{"answer":"最终判断必须结合部署拓扑、合同条款与日志策略。","evidence":"部署拓扑、合同、日志策略"}}],"formulas":[{"id":"model-families-autoregressive-decoder","section":2,"formulaIndex":1,"symbols":[{"name":"p","meaning":"条件概率","evidence":"条件概率"},{"name":"x","meaning":"条件输入","evidence":"x 是条件输入"},{"name":"y","meaning":"完整输出序列","evidence":"y 是完整输出序列"},{"name":"t","meaning":"当前生成位置","evidence":"t 是当前生成位置"}]},{"id":"model-families-diffusion-noising","section":3,"formulaIndex":1,"symbols":[{"name":"x","meaning":"干净样本或带噪样本","evidence":"干净样本"},{"name":"t","meaning":"扩散时间步","evidence":"时间步 t 的带噪样本"},{"name":"α","meaning":"原信号保留比例","evidence":"ᾱₜ 控制还保留多少原信号"},{"name":"ε","meaning":"随机噪声","evidence":"ε 是加入的随机噪声"},{"name":"θ","meaning":"去噪网络参数","evidence":"参数为 θ 的去噪网络"},{"name":"c","meaning":"文本等条件","evidence":"c 是文本等条件"}]},{"id":"model-families-recurrent-state","section":4,"formulaIndex":1,"symbols":[{"name":"x","meaning":"当前位置输入","evidence":"xₜ 是当前位置输入"},{"name":"h","meaning":"历史压缩状态","evidence":"此前历史压缩成的状态"},{"name":"t","meaning":"序列位置编号","evidence":"当前位置输入"},{"name":"A","meaning":"旧状态更新矩阵","evidence":"矩阵 A 更新旧状态"},{"name":"B","meaning":"当前输入写入矩阵","evidence":"B 写入当前输入"},{"name":"C","meaning":"状态读取矩阵","evidence":"矩阵 C 再把状态读成输出"},{"name":"y","meaning":"当前位置输出","evidence":"输出 yₜ"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-26","terms":[{"name":"高维","meaning":"一个样本需要由很多个数值坐标共同描述","purpose":"图像潜变量包含大量位置与通道，因此扩散要同时处理许多坐标","definitionEvidence":"高维表示一个样本需要由很多个数值坐标共同描述","purposeEvidence":"图像潜变量包含大量位置与通道"}]}],"examples":[{"section":6,"evidence":{"setup":"退款请求","rule":"先拆任务与硬约束","steps":"意图分类/检索","interpretation":"组合系统通常比“最大模型全包”更便宜、可测、可控"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分架构、目标、模态和产品层；比较编码器、解码器、扩散与状态空间模型；用约束驱动的流程选择家族；识别品牌名和能力之间的错误推断。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>“模型家族”至少包含四个互相独立的轴<span class=\"dd-badge intuition\">坐标系</span></h2><p class=\"dd-lead\">为什么“它是 Transformer”远远不够？</p><p><b>模型家族</b>在这里不是品牌集合，而是一套描述模型机制与交付方式的坐标。输入是一个具体模型版本或任务需求，输出是架构、训练目标、模态接口和后训练/产品层四项说明。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>轴</th><th>回答的问题</th><th>例子</th></tr></thead><tbody><tr><td>架构</td><td>信息怎样读取、保存与混合？</td><td>编码器、因果解码器、扩散、SSM</td></tr><tr><td>训练目标</td><td>模型被奖励去预测什么？</td><td>掩码词、下一个 token、去噪、对比学习</td></tr><tr><td>模态/接口</td><td>输入输出是什么结构？</td><td>文本、图像、音频、动作、多模态</td></tr><tr><td>后训练/产品</td><td>原始模型外又加了什么？</td><td>指令对齐、RAG、工具、记忆、安全策略</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>先消除一个最常见的混淆：</b>“Transformer”“大语言模型”和“聊天产品”不是同一层。Transformer 是信息流骨架，大语言模型还包含训练目标与数据，聊天产品又叠加后训练、检索、工具和权限。看到其中一个名称，不能自动推出另外两层的能力与边界。</div><p>同一个 Transformer 骨架可以训练成分类编码器、文本生成器或视觉模型；同一个生成模型又可被包装成完全不同的产品。四轴帮助解释“为什么擅长”，却不能只凭家族标签保证质量、隐私或安全，仍要查具体版本并实测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>编码器、解码器与编码器—解码器的信息流不同<span class=\"dd-badge math\">Transformer</span></h2><p class=\"dd-lead\">同样使用注意力，为什么适合的任务不同？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>家族</th><th>注意力可见范围</th><th>常见目标</th><th>天然强项</th></tr></thead><tbody><tr><td>Encoder-only</td><td>双向看完整输入</td><td>掩码 token</td><td>分类、检索表示、抽取</td></tr><tr><td>Decoder-only</td><td>只看当前位置之前</td><td>下一个 token</td><td>开放式生成、续写、上下文学习</td></tr><tr><td>Encoder–decoder</td><td>输入双向；输出因果</td><td>条件序列生成</td><td>翻译、摘要、结构化转换</td></tr></tbody></table></div><p>编码器输入完整序列并输出每个位置的双向表示；因果解码器输入提示与已生成前缀，逐步输出下一个 token；编码器—解码器先编码输入，再让输出端条件生成。“天然强项”不是排他能力，区别在于训练信号与计算路径是否贴合任务。</p><div class=\"dd-formula\" data-formula-id=\"model-families-autoregressive-decoder\"><math display=\"block\" aria-label=\"给定输入 x 时输出序列 y 的概率，等于每个位置 t 的 token y t 在输入 x 和先前输出 y 小于 t 条件下的概率乘积\"><mrow><mi>p</mi><mo>(</mo><mi>y</mi><mo>∣</mo><mi>x</mi><mo>)</mo><mo>=</mo><munder><mo>∏</mo><mi>t</mi></munder><mi>p</mi><mo>(</mo><msub><mi>y</mi><mi>t</mi></msub><mo>∣</mo><msub><mi>y</mi><mrow><mo>&lt;</mo><mi>t</mi></mrow></msub><mo>,</mo><mi>x</mi><mo>)</mo></mrow></math></div><p class=\"dd-formula-note\"><code>x</code> 是条件输入，例如待翻译原文；<code>y</code> 是完整输出序列，<code>t</code> 是当前生成位置，<code>y&lt;t</code> 是此前已生成的 token。乘积符号表示整段输出概率由每一步条件概率相乘得到，因此早期选择会改变后续条件。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>扩散模型学习逐步去噪，不是从左到右续写<span class=\"dd-badge math\">生成</span></h2><p class=\"dd-lead\">为什么图像生成常从噪声开始，并经过很多步？</p><p>前向过程逐步向干净数据加入噪声，训练输入是带噪样本、时间步和可选条件，输出是模型预测的噪声、速度或干净样本。生成时从噪声出发，反复使用这些预测恢复结构，而不是逐像素从左到右续写。</p><div class=\"dd-formula\" data-formula-id=\"model-families-diffusion-noising\"><math display=\"block\" aria-label=\"时间 t 的带噪样本 x t，等于 alpha bar t 的平方根乘干净样本 x zero，加一减 alpha bar t 的平方根乘噪声 epsilon；模型根据 x t、t 和条件 c 预测 epsilon\"><mtable><mtr><mtd><msub><mi>x</mi><mi>t</mi></msub><mo>=</mo><msqrt><msub><mover><mi>α</mi><mo>¯</mo></mover><mi>t</mi></msub></msqrt><msub><mi>x</mi><mn>0</mn></msub><mo>+</mo><msqrt><mrow><mn>1</mn><mo>−</mo><msub><mover><mi>α</mi><mo>¯</mo></mover><mi>t</mi></msub></mrow></msqrt><mi>ε</mi></mtd></mtr><mtr><mtd><msub><mi>ε</mi><mi>θ</mi></msub><mo>(</mo><msub><mi>x</mi><mi>t</mi></msub><mo>,</mo><mi>t</mi><mo>,</mo><mi>c</mi><mo>)</mo><mo>≈</mo><mi>ε</mi></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>x₀</code> 是干净样本，<code>xₜ</code> 是时间步 t 的带噪样本，<code>ᾱₜ</code> 控制还保留多少原信号，<code>ε</code> 是加入的随机噪声。<code>εθ</code> 是参数为 θ 的去噪网络，<code>c</code> 是文本等条件；训练让网络预测实际噪声，生成再按调度器逐步反推。</p><p><b>这里的“高维”是什么意思？</b>高维表示一个样本需要由很多个数值坐标共同描述；例如图像潜变量包含大量位置与通道，所以去噪不是只改一个数字，而是要协调许多坐标。维度多并不自动代表信息更丰富：若数据类型主要是离散规则或要求逐字精确，扩散的连续去噪优势未必适用。</p><p>扩散可以同时修正整幅潜变量，适合连续高维信号；传统采样需要多步，精确文字、离散逻辑与实时延迟常需额外设计。扩散是机制，不等同于图像模态，也可用于音频、视频、动作或离散序列。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>状态空间与递归家族用压缩状态换线性扫描<span class=\"dd-badge math\">长序列</span></h2><p class=\"dd-lead\">不做所有位置两两比较，模型如何携带历史？</p><div class=\"dd-formula\" data-formula-id=\"model-families-recurrent-state\"><math display=\"block\" aria-label=\"时间 t 的隐藏状态 h t 等于状态转移 A 乘上一状态 h t 减一，加输入映射 B 乘当前输入 x t；输出 y t 等于读出 C 乘 h t\"><mtable><mtr><mtd><msub><mi>h</mi><mi>t</mi></msub><mo>=</mo><mi>A</mi><msub><mi>h</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mi>B</mi><msub><mi>x</mi><mi>t</mi></msub></mtd></mtr><mtr><mtd><msub><mi>y</mi><mi>t</mi></msub><mo>=</mo><mi>C</mi><msub><mi>h</mi><mi>t</mi></msub></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>xₜ</code> 是当前位置输入，<code>hₜ₋₁</code> 是此前历史压缩成的状态；矩阵 <code>A</code> 更新旧状态，<code>B</code> 写入当前输入，得到新状态 <code>hₜ</code>，矩阵 <code>C</code> 再把状态读成输出 <code>yₜ</code>。实际 RNN 或 SSM 会加入非线性、门控或输入依赖参数，公式只给出最小信息流。</p><p>对长度 n，注意力分数矩阵有 n² 个位置对：n=1000 时约一百万，n=4000 时约一千六百万；递归或状态空间扫描步数只增加约四倍。但实际速度还取决于硬件并行、状态维度与内核。</p><p>压缩状态会丢掉部分细节：需要精确随机访问、原样复制早期片段时，完整注意力或外部记忆可能更合适。现代系统常做混合，而非二选一。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>多模态模型关键在“在哪里融合”<span class=\"dd-badge intuition\">模态</span></h2><p class=\"dd-lead\">图像加文本输入，是否就形成了统一理解？</p><p>多模态融合把图像、音频等表示与文本表示放进能够相互影响的计算路径。输入是两种或更多模态，输出可以是共享表示、文本、图像或动作；关键不是接口能接收文件，而是哪一层开始允许跨模态信息交互。</p><p>常见路线包括：视觉或音频编码器先提取向量，投影器把向量变成语言模型可读 token；不同模态各自编码后用交叉注意力互相查询；或从头训练统一 token 空间。融合位置决定哪些层能做跨模态交互，数据配对质量决定表示是否真正对齐。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方案</th><th>优点</th><th>限制</th></tr></thead><tbody><tr><td>冻结编码器 + 投影器</td><td>训练便宜、复用成熟模型</td><td>底层表征难共同适配</td></tr><tr><td>交叉注意力融合</td><td>保留模态专长</td><td>接口与训练更复杂</td></tr><tr><td>统一 token/骨架</td><td>交互深入、接口统一</td><td>数据与计算需求高</td></tr></tbody></table></div><p>输出流畅地描述图片只证明生成路径可用，不证明 OCR、空间关系、计数和细粒度定位都可靠；这些能力需要分别设计输入输出明确的测试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>运行示例：为退款助手拆分任务，而非先挑品牌<span class=\"dd-badge eng\">决策图</span></h2><p class=\"dd-lead\">分类工单、读小票、生成回复和执行退款，需要同一个模型包办吗？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 740 330\" role=\"img\" aria-label=\"退款助手按任务约束选择模型家族的决策图\"><defs><marker id=\"mf-a\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#7c8798\"/></marker></defs><rect x=\"275\" y=\"18\" width=\"190\" height=\"52\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"370\" y=\"49\" text-anchor=\"middle\" class=\"svg-t\">退款请求</text><path d=\"M370,70 L370,98\" stroke=\"#7c8798\" marker-end=\"url(#mf-a)\"/><rect x=\"270\" y=\"100\" width=\"200\" height=\"54\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"370\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\">先拆任务与硬约束</text><text x=\"370\" y=\"142\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">准确率·模态·延迟·权限</text><path d=\"M270,128 L120,185\" stroke=\"#7c8798\" marker-end=\"url(#mf-a)\"/><path d=\"M333,154 L290,185\" stroke=\"#7c8798\" marker-end=\"url(#mf-a)\"/><path d=\"M407,154 L450,185\" stroke=\"#7c8798\" marker-end=\"url(#mf-a)\"/><path d=\"M470,128 L620,185\" stroke=\"#7c8798\" marker-end=\"url(#mf-a)\"/><rect x=\"28\" y=\"188\" width=\"180\" height=\"82\" rx=\"9\" fill=\"#21252d\" stroke=\"#5d9f79\"/><text x=\"118\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\">意图分类/检索</text><text x=\"118\" y=\"236\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">编码器或嵌入模型</text><text x=\"118\" y=\"255\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">快、可批量</text><rect x=\"220\" y=\"188\" width=\"145\" height=\"82\" rx=\"9\" fill=\"#21252d\" stroke=\"#8c76bf\"/><text x=\"292\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\">读取小票</text><text x=\"292\" y=\"236\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">视觉编码/OCR</text><text x=\"292\" y=\"255\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">需字段核验</text><rect x=\"377\" y=\"188\" width=\"145\" height=\"82\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"449\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\">生成解释</text><text x=\"449\" y=\"236\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">因果解码器</text><text x=\"449\" y=\"255\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">受政策上下文约束</text><rect x=\"534\" y=\"188\" width=\"180\" height=\"82\" rx=\"9\" fill=\"#21252d\" stroke=\"#c97872\"/><text x=\"624\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\">执行退款</text><text x=\"624\" y=\"236\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">确定性工具/API</text><text x=\"624\" y=\"255\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">鉴权、审批、幂等</text><path d=\"M118,270 L118,303 L620,303 L620,270\" fill=\"none\" stroke=\"#7c8798\"/><text x=\"370\" y=\"322\" text-anchor=\"middle\" class=\"svg-t\">端到端日志与分阶段评测</text></svg><figcaption>图 1　模型家族选择发生在任务拆解之后；高风险动作交给有权限边界的工具，而非让生成模型“凭语言执行”。</figcaption></figure><p>一个小编码器可低成本路由，视觉模型只处理带附件请求，解码器起草解释，退款 API 负责真实状态变化。组合系统通常比“最大模型全包”更便宜、可测、可控。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>把硬约束先过滤，再比较质量—成本前沿<span class=\"dd-badge eng\">选择方法</span></h2><p class=\"dd-lead\">排行榜第一为什么可能不是你的最佳模型？</p><ol><li>定义任务单位与失败代价：每封邮件、每张小票还是每次会话。</li><li>先筛硬约束：数据驻留、许可、模态、上下文、硬件、最大延迟。</li><li>在真实切片上评测候选家族和规模，包含拒答与失败回退。</li><li>比较质量—成本—延迟的 Pareto 前沿，不把异质指标随意加成总分。</li><li>灰度上线，记录模型、提示、检索库与工具版本。</li></ol><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>字段 F1</th><th>P95 延迟</th><th>每千件成本</th><th>结论</th></tr></thead><tbody><tr><td>小编码器 + OCR</td><td>0.94</td><td>180 ms</td><td>¥2</td><td>适合标准票据</td></tr><tr><td>多模态生成器</td><td>0.96</td><td>1.8 s</td><td>¥28</td><td>适合复杂长尾</td></tr><tr><td>规则模板</td><td>0.88</td><td>25 ms</td><td>¥0.2</td><td>只覆盖固定版式</td></tr></tbody></table></div><p>数字是教学算例，不代表真实厂商性能；重要的是用同一数据、同一成功定义测量。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>后训练改变行为，但不会抹去基础机制<span class=\"dd-badge intuition\">后训练</span></h2><p class=\"dd-lead\">“推理模型”“聊天模型”“工具模型”是新架构吗？</p><p>监督微调、偏好优化、强化学习和蒸馏可显著改变回答风格、遵循指令、推理时计算与工具调用，但底层仍可能属于同一解码器家族。产品还可在模型外加入系统提示、RAG、过滤器、缓存和工作流。</p><p>观察到产品能引用资料，不能直接推断基础模型“记住了数据库”；它可能只是运行时检索。观察到产品会调用工具，也不能推断模型拥有权限——真正权限在执行层。</p><div class=\"dd-note\"><b>诊断顺序：</b>先定位错误发生在基础生成、后训练策略、上下文检索、工具参数还是执行权限，再选择修复层。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>开放权重、API 与品牌属于交付层，不是架构家族<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">“开源模型更隐私”或“闭源模型一定更强”为什么都不成立？</p><p>权重许可、训练代码、数据开放程度、托管位置和 API 数据政策是不同问题。开放权重允许自托管，但若部署在第三方云上，数据仍可能外发；API 服务也可能提供零保留与区域选项。品牌下会同时存在多代、多尺寸、多模态和不同上下文版本。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>不能从名称直接推出</th><th>必须查什么</th></tr></thead><tbody><tr><td>隐私与数据保留</td><td>部署拓扑、合同、日志策略</td></tr><tr><td>可商用性</td><td>权重/代码/数据许可证</td></tr><tr><td>工具可靠性</td><td>函数调用评测、权限和重试</td></tr><tr><td>知识新鲜度</td><td>知识截止、检索源与更新时间</td></tr><tr><td>真实版本</td><td>模型 ID、日期、参数和服务档</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">先用四轴定位，再深入具体家族与系统层。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>Transformer 就等于聊天大模型</td><td>同一骨架可配多种目标与模态</td></tr><tr><td>参数更多必然更适合</td><td>任务切片、延迟和约束决定前沿</td></tr><tr><td>多模态就是每项模态都强</td><td>需分别测 OCR、定位、关系和生成</td></tr><tr><td>线性复杂度一定更快更好</td><td>常数、并行性与随机访问能力同样重要</td></tr><tr><td>品牌名可推出隐私与许可</td><td>这些属于具体版本、合同和部署</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>学习方向</th></tr></thead><tbody><tr><td>先修</td><td>监督学习、自监督学习、神经网络</td></tr><tr><td><b>本页核心</b></td><td>架构 × 目标 × 模态 × 产品层</td></tr><tr><td>深入架构</td><td>Transformer、扩散、RNN、SSM、MoE</td></tr><tr><td>落地</td><td>模型选择、评测、部署、RAG、工具调用</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>拆解任务与失败代价</li><li>列出模态、延迟、许可等硬约束</li><li>用信息流与训练目标筛家族</li><li>在真实切片上比较候选</li><li>将生成与高风险执行隔离</li><li>记录完整版本并持续回归</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么 Transformer 不是完整的模型家族说明？</li><li>长度从1000增至4000，注意力位置对约增多少倍？</li><li>退款助手为何不应让生成模型直接执行退款？</li><li>开放权重为什么不自动等于隐私？</li><li>模型选择的第一步是什么？</li><li>假设“模型家族：从信息流与训练目标理解能力边界”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>它只说明部分架构；还需说明编码/解码信息流、训练目标、模态与后训练/产品层。</li><li>从约100万到1600万，增16倍；线性扫描步数约增4倍。</li><li>语言生成不提供鉴权、幂等和审批保证；状态变化应交给有权限边界的确定性工具。</li><li>隐私取决于实际部署、日志、数据流和合同；开放权重也可能托管在第三方环境。</li><li>定义任务单位、失败代价和硬约束，而不是先看品牌排行榜。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1706.03762\" target=\"_blank\" rel=\"noopener\">Attention Is All You Need</a>：编码器—解码器 Transformer</li><li><a href=\"https://arxiv.org/abs/1810.04805\" target=\"_blank\" rel=\"noopener\">BERT</a>：双向编码器与掩码目标</li><li><a href=\"https://cdn.openai.com/better-language-models/language_models_are_unsupervised_multitask_learners.pdf\" target=\"_blank\" rel=\"noopener\">Language Models are Unsupervised Multitask Learners</a>：因果语言建模</li><li><a href=\"https://arxiv.org/abs/2006.11239\" target=\"_blank\" rel=\"noopener\">Denoising Diffusion Probabilistic Models</a>：扩散去噪机制</li><li><a href=\"https://arxiv.org/abs/2312.00752\" target=\"_blank\" rel=\"noopener\">Mamba</a>：选择性状态空间模型</li><li><a href=\"https://arxiv.org/abs/2103.00020\" target=\"_blank\" rel=\"noopener\">Learning Transferable Visual Models From Natural Language Supervision</a>：视觉—语言对比学习</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
